var i=[{title:`Warum Schultern verschieden sind`,text:`Die Schulter hat einen großen Bewegungsumfang und ist auf viel Muskulatur angewiesen, um stabil zu bleiben. Greifen über den Kopf, tiefe Druckpositionen und schnelle Bewegungen können sich von Mensch zu Mensch sehr unterschiedlich anfühlen. Eine Bewegung, die eingeschränkt oder schmerzhaft ist, sagt dir etwas darüber, welche Übungen du wählen solltest. Sie beweist nicht, dass du eine bestimmte Verletzung hast.`},{title:`Die Übung anpassen`,text:`Wenn dich ein Langhantel-Überkopfdrücken stört, probiere ein Kurzhantel-Drücken mit neutralem Griff, ein gestütztes Rudern oder einen Wand-Liegestütz. Ändere Tiefe oder Richtung, bevor du Widerstand hinzufügst. Zugübungen sind ein guter Partner für das Drücken, aber kein festes Verhältnis von Drücken zu Ziehen heilt Schulterschmerz.`},{title:`Kontrolle und allmähliche Gewöhnung`,text:`Nutze, während du eine Bewegung lernst, langsame, kontrollierte Wiederholungen, einen bequemen Bereich und leichte Lasten. Schulterkraft aufzubauen kann allmählich härtere Arbeit erfordern, aber diese Steigerung sollte deine Symptome nicht verschlimmern. Eine Dehnung durch Schmerz zu erzwingen oder immer wieder schwere Überkopfhebungen zu testen bringt dich nicht schneller ans Ziel.`},{title:`Warnzeichen`,text:`Hole bei starkem Schmerz nach einem Sturz, einem Arm, den du nicht bewegen kannst, einer sichtbaren Verformung, starker Schwellung oder neuer Taubheit, die nicht verschwindet, zügig medizinischen Rat. Symptome, die sich nicht bessern, muss ebenfalls eine Fachperson ansehen.`},{title:`TrainUp nutzen`,text:`Füge deine Schulter im Profil unter Einschränkungen hinzu, mit Notizen, und halte deine Ausrüstungsliste aktuell. Der Plan wählt dann nur Übungen, die zu deinen Einschränkungen, deiner Ausrüstung, deinem Level und deiner Koordination passen. Wenn eine Übung während eines Trainings weh tut, tippe auf „Ich habe Schmerzen“, um sie sofort zu beenden. Sie bleibt aus deinen Plänen draußen, bis du sie im Profil wieder aufnimmst. Übungen auf diese Weise auszutauschen behandelt kein Impingement, keine Rotatorenmanschettenerkrankung und keinen anderen bestimmten Zustand.`}];var t=[{label:`NHS: Schulterschmerzen und Warnzeichen`,url:`https://www.nhs.uk/symptoms/shoulder-pain/`},{label:`ACSM-Positionspapier 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};